      Value<double>? amount,
      Value<String>? category,
      Value<String>? currency,
      Value<String?>? note,
      Value<DateTime>? date,
      Value<DateTime>? createdAt}) {
    return ExpensesCompanion(
      id: id ?? this.id,
      title: title ?? this.title,
      amount: amount ?? this.amount,
      category: category ?? this.category,
      currency: currency ?? this.currency,
      note: note ?? this.note,
      date: date ?? this.date,
